import{_ as o,r as a,o as i,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Theme Localization - October CMS - 4.x","titleTemplate":false,"description":"Learn how to translate messages inside CMS themes.","frontmatter":{"subtitle":"Learn how to translate messages inside CMS themes."},"headers":[{"level":3,"title":"Localization File Structure","slug":"localization-file-structure","link":"#localization-file-structure","children":[]},{"level":2,"title":"Scanning for Messages","slug":"scanning-for-messages","link":"#scanning-for-messages","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/multisite/localization.md","filePath":"4.x/cms/multisite/localization.md"}'),p={name:"4.x/cms/multisite/localization.md"};function d(u,e,g,h,m,f){const n=a("pre-heading"),t=a("post-heading");return i(),l("div",null,[s(n),e[0]||(e[0]=c("h1",null,"Theme Localization",-1)),s(t),e[1]||(e[1]=r(`<div class="custom-block aside"><p>View the <a href="./multisite.html">Multisite article</a> to learn how to set the active language for your website.</p></div><p>Themes can provide localization keys through files placed in the <strong>lang</strong> subdirectory of the theme&#39;s directory. These localization keys are registered automatically and can be used inside the theme contents or as backend form labels similar to <a href="./../../extend/multisite/localization.html">plugin localization</a>.</p><h3 id="localization-file-structure"><a href="#localization-file-structure" class="header-anchor">#</a> Localization File Structure</h3><p>Below is an example of the theme&#39;s <strong>lang</strong> directory.</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       └── <code>lang</code>  <em>← Localization Directory</em>
|           ├── en.json  <em>← Localization File</em>
|           └── fr.json  <em>← Localization File</em></p>
</code></pre><p>The localization file is a JSON file where strings use the &quot;default&quot; translation of the string as the key. For example, if your application has a French translation, you should create a <code>lang/fr.json</code> file.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;I love programming.&quot;</span><span class="token operator">:</span> <span class="token string">&quot;j&#39;adore programmer&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You are also able to define code-based keys by using the complete language key in the JSON file, for example, <code>theme.options.website_name</code> for the <strong>acme</strong> theme can be used.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;theme.options.website_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Language strings can be accessed in your theme files using the <code>__()</code> Twig function.</p><div class="custom-block tip"><p>View <a href="./../../markup/function/trans.html">the markup guide</a> to learn more about translation in Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- j&#39;adore programmer --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>I love programming.<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>

<span class="token comment">&lt;!-- October CMS --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>theme.options.website_name<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div></div><h2 id="scanning-for-messages"><a href="#scanning-for-messages" class="header-anchor">#</a> Scanning for Messages</h2><p>Instead of adding every localization key by hand, the theme templates can be scanned for translatable strings. The scanner inspects the markup of every layout, page and partial in the theme, collecting string literals passed to the translation functions (<code>__()</code>, <code>trans()</code>, <code>trans_choice()</code>) and filters (<code>|trans</code>, <code>|_</code>, <code>|__</code>, <code>|trans_choice</code>).</p><p>Language files are managed in the CMS Editor area of the admin panel, in the <strong>Languages</strong> section of the navigator. When editing a language file, click the <strong>Scan for Messages</strong> button in the toolbar and any newly discovered messages are added to the file as keys with empty translations, keeping the existing values untouched.</p><p>The same operation is available with the <code>theme:scan</code> artisan command, where new keys are written to the language file of the primary site locale.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:scan mytheme
</code></pre></div><p>Use the <code>--locale</code> option to target a different language file, or the <code>--dry-run</code> option to list the found messages without writing anything.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:scan mytheme <span class="token parameter variable">--locale</span><span class="token operator">=</span>fr --dry-run
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./multisite.html">Multisite</a></li><li><a href="./../../extend/multisite/localization.html">Plugin Localization</a></li></ul></div>`,20))])}const b=o(p,[["render",d]]);export{_ as __pageData,b as default};
